import "server-only";

import { cache } from "react";

import type { StatusLista } from "@/features/listas/opcoes";
import type { Reacao } from "@/features/reacoes/opcoes";
import { createClient } from "@/lib/supabase/server";
import type { ClienteSupabase } from "@/lib/supabase/token";

export type ItemLista = {
  tmdbId: number;
  status: StatusLista;
  titulo: string;
  posterPath: string | null;
  ano: number | null;
  /** Reação dada ao filme, se houver (spec `reacoes`). */
  reacao: Reacao | null;
};

/** Filmes nas duas listas do usuário logado, do mais recente para o mais antigo. */
export const obterItensLista = cache(async (cliente?: ClienteSupabase): Promise<ItemLista[]> => {
  const supabase = cliente ?? (await createClient());
  const [itens, reacoes] = await Promise.all([
    supabase
      .from("lista_itens")
      .select("tmdb_id, status, titulo, poster_path, ano")
      .eq("tipo", "filme")
      .order("adicionado_em", { ascending: false }),
    supabase.from("reacoes").select("tmdb_id, reacao").eq("tipo", "filme"),
  ]);

  if (itens.error) {
    console.error("[listas] falha ao ler:", itens.error.code, itens.error.message);
    throw new Error("Não foi possível carregar suas listas.");
  }
  const reacaoPorFilme = new Map((reacoes.data ?? []).map((r) => [r.tmdb_id, r.reacao]));

  return itens.data.map((linha) => ({
    tmdbId: linha.tmdb_id,
    status: linha.status,
    titulo: linha.titulo,
    posterPath: linha.poster_path,
    ano: linha.ano,
    reacao: reacaoPorFilme.get(linha.tmdb_id) ?? null,
  }));
});

/** IDs dos filmes nas duas listas, para o motor não recomendá-los. */
export async function idsNasListas(cliente?: ClienteSupabase): Promise<number[]> {
  const supabase = cliente ?? (await createClient());
  const { data, error } = await supabase.from("lista_itens").select("tmdb_id").eq("tipo", "filme");
  if (error) {
    console.error("[listas] falha ao ler IDs:", error.code, error.message);
    return [];
  }
  return data.map((linha) => linha.tmdb_id);
}

/** Lista em que o filme está, ou `null`. */
export async function obterStatusLista(tmdbId: number, cliente?: ClienteSupabase): Promise<StatusLista | null> {
  const supabase = cliente ?? (await createClient());
  const { data } = await supabase
    .from("lista_itens")
    .select("status")
    .eq("tipo", "filme")
    .eq("tmdb_id", tmdbId)
    .maybeSingle();
  return data?.status ?? null;
}
=== src/features/listas/gravar.ts
import "server-only";

import type { StatusLista } from "@/features/listas/opcoes";
import type { ClienteSupabase } from "@/lib/supabase/token";
import { obterFilme } from "@/lib/tmdb/filmes";
import type { FilmeDetalhes } from "@/lib/tmdb/tipos";

export type ResultadoDefinir<T> =
  | { ok: true; titulo: string | null; anterior: T | null; atual: T | null }
  | { ok: false; erro: "filme-nao-encontrado" | "tmdb" | "banco" };

type BuscarFilme = (id: number) => Promise<FilmeDetalhes | null>;

/**
 * Deixa o filme na lista pedida (`null` tira das listas). É idempotente: repetir não muda nada.
 * Os dados do filme vêm do TMDB no servidor, nunca de quem chama. Lê, grava e apaga só a
 * linha `tipo = 'filme'`: uma série de mesmo ID fica intacta.
 */
export async function definirLista(
  supabase: ClienteSupabase,
  usuarioId: string,
  tmdbId: number,
  status: StatusLista | null,
  buscarFilme: BuscarFilme = obterFilme,
): Promise<ResultadoDefinir<StatusLista>> {
  const { data: atual, error: erroLeitura } = await supabase
    .from("lista_itens")
    .select("status, titulo")
    .eq("tipo", "filme")
    .eq("tmdb_id", tmdbId)
    .maybeSingle();
  if (erroLeitura) {
    console.error("[listas] falha ao ler:", erroLeitura.code, erroLeitura.message);
    return { ok: false, erro: "banco" };
  }
  const anterior = atual?.status ?? null;

  if (status === null) {
    if (atual) {
      const { error } = await supabase
        .from("lista_itens")
        .delete()
        .eq("tipo", "filme")
        .eq("tmdb_id", tmdbId);
      if (error) {
        console.error("[listas] falha ao remover:", error.code, error.message);
        return { ok: false, erro: "banco" };
      }
    }
    return { ok: true, titulo: atual?.titulo ?? null, anterior, atual: null };
  }

  if (atual && anterior === status) return { ok: true, titulo: atual.titulo, anterior, atual: status };

  let filme: FilmeDetalhes | null;
  try {
    filme = await buscarFilme(tmdbId);
  } catch {
    return { ok: false, erro: "tmdb" };
  }
  if (!filme) return { ok: false, erro: "filme-nao-encontrado" };

  const { error } = await supabase.from("lista_itens").upsert({
    usuario_id: usuarioId,
    tipo: "filme",
    tmdb_id: tmdbId,
    status,
    titulo: filme.titulo,
    poster_path: filme.posterPath,
    ano: filme.ano,
    generos: filme.generos.map((genero) => genero.id),
    // Ao entrar ou trocar de lista, o filme vai para o topo da aba.
    adicionado_em: new Date().toISOString(),
  });
  if (error) {
    console.error("[listas] falha ao salvar:", error.code, error.message);
    return { ok: false, erro: "banco" };
  }
  return { ok: true, titulo: filme.titulo, anterior, atual: status };
}
