export type TamanhoImagem = "w92" | "w185" | "w342" | "w500" | "w780" | "w1280" | "original";

/** URL do CDN de imagens do TMDB. Pode ser usado no servidor e no navegador. */
export function urlImagem(path: string | null, tamanho: TamanhoImagem): string | null {
  return path ? `https://image.tmdb.org/t/p/${tamanho}${path}` : null;
}
}

export default async function FilmePage({ params }: PageProps<"/filme/[id]">) {
  const filme = await buscarFilme((await params).id);
  if (!filme) notFound();
  const [reacao, statusLista] = await Promise.all([
    obterReacao(filme.id),
    obterStatusLista(filme.id),
  ]);

  return (
    <div className="mx-auto flex w-full max-w-6xl flex-1 flex-col gap-10 px-4 py-8">
      <Voltar />

      <CabecalhoFilme
        filme={filme}
        acoes={
          <>
            <BotoesReacao key={`r-${reacao}`} tmdbId={filme.id} atual={reacao} />
            <BotoesLista key={`l-${statusLista}`} tmdbId={filme.id} atual={statusLista} />
          </>
        }
      />

      <Secao titulo="Sinopse">
        <p className="max-w-3xl leading-relaxed">
          {filme.sinopse || "Sinopse não disponível em português."}
        </p>
        {filme.direcao.length > 0 && (
          <p className="text-muted-foreground text-sm">Direção: {filme.direcao.join(", ")}</p>
        )}
      </Secao>

      {filme.trailerYoutube && (
        <Secao titulo="Trailer">
          <Trailer chave={filme.trailerYoutube} titulo={filme.titulo} origem="filme" />
        </Secao>
      )}

      <Secao titulo="Onde assistir no Brasil">
        <OndeAssistir dados={filme.ondeAssistir} />
      </Secao>

      {filme.elenco.length > 0 && (
        <Secao titulo="Elenco">
          <Elenco pessoas={filme.elenco} />
        </Secao>
      )}

