      {nomes.length > 0 && (
        <p className="text-muted-foreground text-sm">
          {rotulo}: {nomes.join(", ")}
        </p>
      )}
    </Secao>
  );
}

/** Botões de reação e de lista do título; a `key` recria cada grupo quando o servidor muda o valor. */
